#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MOD 1337
#define MAX_B 2000

static int mod_pow(int base, int exp) {
    long long x = base % MOD;
    long long result = 1;
    while (exp > 0) {
        if (exp & 1) {
            result = (result * x) % MOD;
        }
        x = (x * x) % MOD;
        exp >>= 1;
    }
    return (int)result;
}

int superPow(int a, int* b, int bSize) {
    long long result = 1;
    for (int i = 0; i < bSize; ++i) {
        result = (long long)mod_pow((int)result, 10) * mod_pow(a, b[i]) % MOD;
    }
    return (int)result;
}

