class Solution {
    private static final int MOD = 1337;

    private int modPow(int base, int exp) {
        long x = base % MOD;
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) != 0) {
                result = (result * x) % MOD;
            }
            x = (x * x) % MOD;
            exp >>= 1;
        }
        return (int) result;
    }

    public int superPow(int a, int[] b) {
        long result = 1;
        for (int digit : b) {
            result = (long) modPow((int) result, 10) * modPow(a, digit) % MOD;
        }
        return (int) result;
    }
}

